        if[current_char ~ ".";
            if[(i + 1) < count[x];
                if[x[i + 1] ~ "|";
                    notes:notes,enlist 1;
                    i:i + 2;
                    continue;
                ];
            ];

            i:i + 1;
            ];

        if[not (current_char ~ " ") or (current_char ~ "\t") or (current_char ~ "\n") or (current_char ~ "\r");
            i:i + 1;
            ];
    ];

    :notes;
    };
