find_zero:{[x]
    a: x[0];
    b: x[1];
    c: x[2];
    d: x[3];

    a_over_4: a % 4;
    b_over_2: b % 2;
    f: (b_over_2) * (b_over_2) - c;
    g: a_over_4 * d - (b_over_2) * (b_over_2) * (b_over_2);

    h: (f * f * f) % 27 + (g * g) % 4;

    if[h <= 0;
        z: acos(-1 * (g % 2) % sqrt((f * f * f) % 27));
        w: sqrt(f % 3);
        x1: 2 * w * cos(z % 3) - b_over_2;
        x2: 2 * w * cos((z + 2 * 3.141592653589793) % 3) - b_over_2;
        x3: 2 * w * cos((z + 4 * 3.141592653589793) % 3) - b_over_2;
        x_vals: (x1; x2; x3);
    ];

    if[h > 0;
        sq_h: sqrt(h);
        u: ((-g % 2) + sq_h);
        v: ((-g % 2) - sq_h);

        u: signum[u] * abs[u] % 3;
        v: signum[v] * abs[v] % 3;

        x1: (u + v) - b_over_2;
        x_vals: (x1);
    ];

    if[0 > count[x_vals];
        :0N;
    ];

    root: first[x_vals];

    if[not (root in 0);
        root: root;
    ];

    :root;
    }
