find_zero:{[x]
    n: count[x];
    p: n - 1;
    x_vals: 1 + til n;
    y_vals: ();

    i: 0;

    while[i < n;
        y_vals: y_vals, enlist sum[x * (x_vals[i]) xexp (reverse til n)];
        i: i + 1;
    ];

    i: 0;

    while[i < (n - 1);
        if[sign[y_vals[i]] <> sign[y_vals[i + 1]];
            a: x_vals[i];
            b: x_vals[i + 1];
            fa: y_vals[i];
            fb: y_vals[i + 1];

            tolerance: 1e-10;
            max_iter: 1000;
            iter: 0;

            while[((b - a) > tolerance) and (iter < max_iter);
                c: (a + b) % 2;
                fc: sum[x * (c xexp (reverse til n))];

                if[abs[fc] < tolerance;
                    :c;
                ];

                if[sign[fc] = sign[fa];
                    a: c;
                    fa: fc;
                ];

                if[sign[fc] = sign[fb];
                    b: c;
                    fb: fc;
                ];

                iter: iter + 1;
            ];

            : (a + b) % 2;
        ];

        i: i + 1;
    ];

    : 0N;
    };
