    spaces_only: where (parts = "");
    non_spaces: where not (parts = "");

    if[0 = count[spaces_only];
        :raze parts;
    ];

    groups: group[spaces_only];

    result: x;

    indices: desc key[groups] where (count each value[groups]) > 2;

    i: 0;

    while[i < count[indices];
        idx: indices[i];
        count_spaces: count[groups[idx]];

        start: idx;
        end: idx + count_spaces - 1;

        result[start]: "-";
        result[start + 1 + til[count_spaces - 1]]: "";

        i: i + 1;
    ];

    result: ssr[result; " "; "_"];

    :result;
    }
```

