fix_spaces:{[text]
    spaces:where text=" ";
    if[0=count spaces;
        :text;
    ];

    run_lengths:count each (group spaces) asc distinct group spaces;
    long_runs:where run_lengths>2;

    if[0=count long_runs;
        :ssr[text;" ";"_"];
    ];

    result:text;

    i:0;

    while[i<count long_runs;
        start:spaces[(2*long_runs[i])];
        len:run_lengths[long_runs[i]];

        result:start+enlist "-" ;
        result:(start+len)-1 _ result;

        i:i+1;
    ];

    result:ssr[result;" ";"_"];

    :result;
    };
