get_max_triples:{[x]
    if[x < 3;
        :0;
    ];

    a:({(x * x) - x + 1} each 1 + til x);
    mod_a:(a mod 3);

    count0:count(where mod_a = 0);
    count1:count(where mod_a = 1);
    count2:count(where mod_a = 2);

    result:((count0 * (count0 - 1)) * (count0 - 2)) div 6;
    result:result + (count1 * (count1 - 1)) div 2 * count2;
    result:result + (count2 * (count2 - 1)) div 2 * count1;
    result:result + count0 * count1 * count2;

    :result;
    };
```

